```java
// Fixed code snippet: Using prepared statements to prevent SQL injection
public class SafeExample {
    public static void main(String[] args) {
        String userInput = "admin' OR '1'='1"; // Malicious input

        // Good practice: Use JDBC PreparedStatement with parameterized queries
        String sqlQuery = "SELECT * FROM users WHERE username = ? AND password = ?";

        try (Connection conn = DriverManager.getConnection("jdbc:mysql://localhost:3306/mydb", "user", "pass");
             PreparedStatement stmt = conn.prepareStatement(sqlQuery)) {

            // Set parameters safely, preventing SQL injection
            stmt.setString(1, userInput);
            stmt.setString(2, "password");

            ResultSet rs = stmt.executeQuery();
            while (rs.next()) {
                System.out.println("User found: " + rs.getString("username"));
            }
        } catch (SQLException e) {
            e.printStackTrace();
        }
    }
}
```

