```java
// [extrait de code 2]
// Correction : Utilisation sécurisée avec vérification et échappement des données
public String getUserData(String param) {
    // Vérification simple (selon le contexte métier)
    if (param == null || param.isEmpty() || !param.matches("^[a-zA-Z0-9_ ]+$")) {
        throw new IllegalArgumentException("Paramètre invalide");
    }

    // Échappement pour éviter les injections SQL
    String escapedParam = param.replace("'", "''");

    // Construction sécurisée de la requête
    return "SELECT * FROM users WHERE name = '" + escapedParam + "'";
}
```

