```java
// खराब कोड स्निपेट: अनुचित उपयोग वेब अप्लिकेशन में कमजोरियों की ओर ले जा सकता है
public class VulnerableServlet extends HttpServlet {
    protected void doPost(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
        String userInput = request.getParameter("username");
        // अनुचित तरीके से इनपुट को स्टोर कर रहे हैं - एक स्थाई स्ट्रिंग चैन पर आधारित है
        String query = "SELECT * FROM users WHERE username = '" + userInput + "'";
        Statement stmt = connection.createStatement();
        ResultSet rs = stmt.executeQuery(query);
        // यह कमजोर है क्योंकि SQL इंजेक्शन की संभावना है
    }
}
***
// ठीक किया गया कोड स्निपेट: अनुचित उपयोग को दूर करते हुए SQL इंजेक्शन को रोका गया
public class SecureServlet extends HttpServlet {
    protected void doPost(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
        String userInput = request.getParameter("username");
        // PreparedStatement का उपयोग करते हुए इनपुट को सुरक्षित रूप से दबाया जाता है
        String query = "SELECT * FROM users WHERE username = ?";
        try (PreparedStatement pstmt = connection.prepareStatement(query)) {
            pstmt.setString(1, userInput);
            ResultSet rs = pstmt.executeQuery();
            // अब SQL इंजेक्शन की संभावना नहीं है
        }
    }
}
```

