// Хороший: безопасное использование API с валидацией и ограничением прав
public class SafeAPI {
    public static String getSecretData(String input) {
        if (input == null || input.trim().isEmpty()) {
            throw new IllegalArgumentException("Input cannot be empty");
        }

        // Проверка на длину и специальные символы
        if (input.length() > 100 || containsInvalidChars(input)) {
            throw new IllegalArgumentException("Input is too long or contains invalid characters");
        }

        // Использование безопасного сервиса с ограниченными привилегиями
        return new RestrictedSecretService().fetchSafeData(input);
    }

    private static boolean containsInvalidChars(String s) {
        return s.contains("/") || s.contains("\\") || s.contains(":");
    }
}
