// Corretto: utilizzo di JDBC con parametrizzazione per prevenire SQL injection
String username = "admin";
String password = "password123"; // In pratica, questa dovrebbe essere memorizzata in un file di configurazione sicuro

// Connessione al database con crittografia TLS e driver aggiornato
String url = "jdbc:mysql://localhost:3306/mydb?useSSL=true&requireSSL=true";
Connection conn = DriverManager.getConnection(url, username, password);

// Esempio di preparazione della query per evitare SQL injection
PreparedStatement pstmt = conn.prepareStatement("SELECT * FROM users WHERE name = ?");
pstmt.setString(1, username);
ResultSet rs = pstmt.executeQuery();
```

