[frammento di codice 2]  
```java
// Corretto: uso di PreparedStatement per prevenire SQL injection, validazione degli input
public class SecureAPIExample {
    public static void main(String[] args) {
        String userInput = "'; DROP TABLE users;--";

        // Validazione dell'input prima di usarlo
        if (!isValidUsername(userInput)) {
            System.err.println("Input non valido.");
            return;
        }

        try {
            // Utilizzo di PreparedStatement per evitare SQL injection
            String query = "SELECT * FROM users WHERE username = ?";
            java.sql.PreparedStatement stmt = null;
            try (java.sql.Connection conn = java.sql.DriverManager.getConnection("jdbc:mysql://localhost:3306/mydb", "user", "password")) {
                stmt = conn.prepareStatement(query);
                stmt.setString(1, userInput);
                java.sql.ResultSet rs = stmt.executeQuery();
                while (rs.next()) {
                    System.out.println("Utente trovato: " + rs.getString("username"));
                }
            } catch (java.sql.SQLException e) {
                System.err.println("Errore JDBC: " + e.getMessage());
            }
        } catch (Exception e) {
            System.err.println("Errore generale: " + e.getMessage());
        }
    }

    // Funzione di validazione semplice ma utile
    private static boolean isValidUsername(String input) {
        return input.matches("[a-zA-Z0-9_]{3,20}");
    }
}
```

